mapper.sql:
FROM system_users u WHERE u.tenant_id = #{query.tenantId} AND u.status = 0 AND u.deleted = b'0' AND EXISTS ( SELECT 1 FROM system_user_role ur JOIN system_role r ON r.id = ur.role_id WHERE ur.user_id = u.id AND ur.tenant_id = u.tenant_id AND ur.deleted = b'0' AND r.tenant_id = u.tenant_id AND r.status = 0 AND r.deleted = b'0'
AND r.code IN #{role}
AND 1 = 0
)

sql.if:
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%')
     OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%')
     OR u.email LIKE CONCAT('%', #{query.keyword}, '%')

        OR u.dept_id IN
        #{dept}

)
